"""Accuracy assertions for the sliding-window-counter approximation."""

from __future__ import annotations

import os
import re

from harness import PATTERNS, LIMIT, replay


def _run(key):
    for k, _, gen in PATTERNS:
        if k == key:
            return replay(gen())
    raise KeyError(key)


def test_steady_disagreement_rate_under_5_percent():
    total, _, _, disagreements, false_allows = _run("steady_8rps")
    assert total > 0
    assert disagreements / total < 0.05, (
        f"disagreement rate {disagreements / total:.2%} >= 5% on steady pattern"
    )
    # The approximation must never over-admit by much either.
    assert false_allows / total < 0.05


def test_report_exists_with_all_three_rows():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "accuracy_report.md")
    assert os.path.exists(path), "accuracy_report.md not found; run harness.py first"
    content = open(path).read()
    for key, label, _ in PATTERNS:
        assert label in content, f"report missing row for pattern '{label}'"
    # Sanity: each pattern row is a real markdown table row with numeric cells.
    rows = [ln for ln in content.splitlines() if ln.startswith("|") and label_marker(ln)]
    assert len(rows) == len(PATTERNS)


def label_marker(line):
    return any(label in line for _, label, _ in PATTERNS) and re.search(r"\d+", line)

